import java.util.Queue;
import java.util.LinkedList;

public class GridBFS {
    static class Position {
        int row, col, dist;
        Position(int r, int c, int d) { row = r; col = c; dist = d; }
    }

    public static int bfsShortestPath(int[][] grid, int sr, int sc) {
        int rows = grid.length;
        int cols = grid[0].length;
        boolean[][] visited = new boolean[rows][cols];
        Queue<Position> queue = new LinkedList<>();

        int[] dr = {-1, 1, 0, 0};
        int[] dc = {0, 0, -1, 1};

        queue.offer(new Position(sr, sc, 0));
        visited[sr][sc] = true;

        while (!queue.isEmpty()) {
            Position p = queue.poll();
            if (p.row == rows - 1 && p.col == cols - 1) {
                return p.dist;
            }

            for (int i = 0; i < 4; i++) {
                int nr = p.row + dr[i];
                int nc = p.col + dc[i];
                if (nr >= 0 && nr < rows && nc >= 0 && nc < cols &&
                    grid[nr][nc] == 0 && !visited[nr][nc]) {
                    visited[nr][nc] = true;
                    queue.offer(new Position(nr, nc, p.dist + 1));
                }
            }
        }
        return -1;  // No path found
    }
}
