using namespace std;

struct Position { int row, col, dist; };

int bfsShortestPath(int grid[][10], int rows, int cols) {

    bool visited[10][10] = {false};

    queue<Position> q;



    int dr[] = {-1, 1, 0, 0};

    int dc[] = {0, 0, -1, 1};



    q.push({0, 0, 0});

    visited[0][0] = true;



    while (!q.empty()) {

        Position p = q.front();

        q.pop();



        if (p.row == rows - 1 && p.col == cols - 1) {

            return p.dist;

        }



        for (int i = 0; i < 4; i++) {

            int nr = p.row + dr[i];

            int nc = p.col + dc[i];

            if (nr >= 0 && nr < rows && nc >= 0 && nc < cols &&

